using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using Microsoft.Win32.SafeHandles;
public sealed class M12SuspendedProcess : IDisposable {
    private const uint CreateSuspended=4, CreateNoWindow=0x08000000, KillOnClose=0x2000, StartfUseStdHandles=0x100, HandleFlagInherit=1;
    private const int ExtendedLimits=9, ProcessIdList=3;
    private readonly IntPtr processHandle, jobHandle; private readonly SafeFileHandle stdoutRead, stderrRead;
    private M12SuspendedProcess(IntPtr process, IntPtr job, int pid, SafeFileHandle output, SafeFileHandle error) { processHandle=process;jobHandle=job;ProcessId=pid;stdoutRead=output;stderrRead=error;ManagedProcess=Process.GetProcessById(pid); }
    public int ProcessId { get; } public Process ManagedProcess { get; }
    public Stream StandardOutput => new FileStream(stdoutRead, FileAccess.Read, 4096, false);
    public Stream StandardError => new FileStream(stderrRead, FileAccess.Read, 4096, false);
    public static M12SuspendedProcess Start(string executable, string[] args, string workingDirectory) {
        SafeFileHandle outRead=null!,outWrite=null!,errRead=null!,errWrite=null!; IntPtr process=IntPtr.Zero,thread=IntPtr.Zero,job=IntPtr.Zero;
        try {
            var attrs=new SecurityAttributes { nLength=Marshal.SizeOf<SecurityAttributes>(), bInheritHandle=1 };
            if(!CreatePipe(out outRead,out outWrite,ref attrs,0)||!SetHandleInformation(outRead,HandleFlagInherit,0)||!CreatePipe(out errRead,out errWrite,ref attrs,0)||!SetHandleInformation(errRead,HandleFlagInherit,0)) throw new InvalidOperationException();
            var startup=new StartupInfo { cb=Marshal.SizeOf<StartupInfo>(),dwFlags=StartfUseStdHandles,hStdInput=GetStdHandle(-10),hStdOutput=outWrite.DangerousGetHandle(),hStdError=errWrite.DangerousGetHandle() };
            var commandLine=new StringBuilder(BuildCommandLine(executable,args));
            if(!CreateProcess(null,commandLine,IntPtr.Zero,IntPtr.Zero,true,CreateSuspended|CreateNoWindow,IntPtr.Zero,workingDirectory,ref startup,out var pi)) throw new InvalidOperationException();
            process=pi.hProcess;thread=pi.hThread;job=CreateJobObject(IntPtr.Zero,null);if(job==IntPtr.Zero)throw new InvalidOperationException();
            var limits=new ExtendedLimitInformation { BasicLimitInformation=new BasicLimitInformation { LimitFlags=KillOnClose } };
            if(!SetInformationJobObject(job,ExtendedLimits,ref limits,(uint)Marshal.SizeOf<ExtendedLimitInformation>())||!AssignProcessToJobObject(job,process)||ResumeThread(thread)==uint.MaxValue)throw new InvalidOperationException();
            if(!CloseHandle(thread))throw new InvalidOperationException();thread=IntPtr.Zero;outWrite.Dispose();outWrite=null!;errWrite.Dispose();errWrite=null!;
            return new M12SuspendedProcess(process,job,pi.dwProcessId,outRead,errRead);
        } catch { var failures=new List<Exception>();try{if(process!=IntPtr.Zero)TerminateProcess(process,1);}catch(Exception e){failures.Add(e);}try{if(process!=IntPtr.Zero)WaitForSingleObject(process,2000);}catch(Exception e){failures.Add(e);}try{if(job!=IntPtr.Zero)TerminateJobObject(job,1);}catch(Exception e){failures.Add(e);}try{if(thread!=IntPtr.Zero)CloseHandle(thread);}catch(Exception e){failures.Add(e);}try{if(process!=IntPtr.Zero)CloseHandle(process);}catch(Exception e){failures.Add(e);}try{if(job!=IntPtr.Zero)CloseHandle(job);}catch(Exception e){failures.Add(e);}try{outRead?.Dispose();outWrite?.Dispose();errRead?.Dispose();errWrite?.Dispose();}catch(Exception e){failures.Add(e);}if(failures.Count>0)throw new AggregateException(failures);throw; }
    }
    private static string BuildCommandLine(string exe,string[] args){var b=new StringBuilder(Quote(exe));foreach(var a in args)b.Append(' ').Append(Quote(a));return b.ToString();}
    private static string Quote(string value){var b=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='\"'){b.Append('\\',slashes*2+1).Append('\"');slashes=0;continue;}b.Append('\\',slashes).Append(c);slashes=0;}b.Append('\\',slashes*2).Append('\"');return b.ToString();}
    public int ActiveProcesses { get { IntPtr buffer=Marshal.AllocHGlobal(65536);try{if(!QueryInformationJobObject(jobHandle,ProcessIdList,buffer,65536,IntPtr.Zero))throw new InvalidOperationException();return Marshal.ReadInt32(buffer);}finally{Marshal.FreeHGlobal(buffer);} } }
    public int[] ProcessIds { get { IntPtr buffer=Marshal.AllocHGlobal(65536);try{if(!QueryInformationJobObject(jobHandle,ProcessIdList,buffer,65536,IntPtr.Zero))throw new InvalidOperationException();int count=Marshal.ReadInt32(buffer,4);var ids=new int[count];for(int i=0;i<count;i++)ids[i]=unchecked((int)Marshal.ReadInt64(buffer,8+i*IntPtr.Size));return ids;}finally{Marshal.FreeHGlobal(buffer);} } }
    public void Terminate(){if(!TerminateJobObject(jobHandle,1))throw new InvalidOperationException();}
    public bool WaitForZero(int milliseconds){long end=Environment.TickCount64+milliseconds;while(Environment.TickCount64<=end){if(ActiveProcesses==0)return true;System.Threading.Thread.Sleep(25);}return ActiveProcesses==0;}
    public void Dispose(){var failures=new List<Exception>();try{if(ActiveProcesses>0&&!TerminateJobObject(jobHandle,1))throw new InvalidOperationException();if(!WaitForZero(2000))throw new TimeoutException();}catch(Exception e){failures.Add(e);}try{stdoutRead.Dispose();}catch(Exception e){failures.Add(e);}try{stderrRead.Dispose();}catch(Exception e){failures.Add(e);}try{if(processHandle!=IntPtr.Zero&&!CloseHandle(processHandle))throw new InvalidOperationException();}catch(Exception e){failures.Add(e);}try{if(jobHandle!=IntPtr.Zero&&!CloseHandle(jobHandle))throw new InvalidOperationException();}catch(Exception e){failures.Add(e);}if(failures.Count>0)throw new AggregateException(failures);}
    [StructLayout(LayoutKind.Sequential)]private struct StartupInfo{public int cb;public IntPtr lpReserved,lpDesktop,lpTitle;public int dwX,dwY,dwXSize,dwYSize,dwXCountChars,dwYCountChars,dwFillAttribute;public uint dwFlags;public short wShowWindow,cbReserved2;public IntPtr lpReserved2,hStdInput,hStdOutput,hStdError;}
    [StructLayout(LayoutKind.Sequential)]private struct SecurityAttributes{public int nLength;public IntPtr lpSecurityDescriptor;public int bInheritHandle;}
    [StructLayout(LayoutKind.Sequential)]private struct ProcessInformation{public IntPtr hProcess,hThread;public int dwProcessId,dwThreadId;}
    [StructLayout(LayoutKind.Sequential)]private struct BasicLimitInformation{public long PerProcessUserTimeLimit,PerJobUserTimeLimit;public uint LimitFlags;public UIntPtr MinimumWorkingSetSize,MaximumWorkingSetSize;public uint ActiveProcessLimit;public UIntPtr Affinity;public uint PriorityClass,SchedulingClass;}
    [StructLayout(LayoutKind.Sequential)]private struct IoCounters{public ulong ReadOperations,WriteOperations,OtherOperations,ReadBytes,WriteBytes,OtherBytes;}
    [StructLayout(LayoutKind.Sequential)]private struct ExtendedLimitInformation{public BasicLimitInformation BasicLimitInformation;public IoCounters IoInfo;public UIntPtr ProcessMemoryLimit,JobMemoryLimit,PeakProcessMemoryUsed,PeakJobProcessUsed;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]private static extern bool CreatePipe(out SafeFileHandle read,out SafeFileHandle write,ref SecurityAttributes attributes,int size);
    [DllImport("kernel32.dll",SetLastError=true)]private static extern bool SetHandleInformation(SafeFileHandle handle,uint mask,uint flags);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]private static extern bool CreateProcess(string application,StringBuilder commandLine,IntPtr processAttributes,IntPtr threadAttributes,bool inheritHandles,uint flags,IntPtr environment,string currentDirectory,ref StartupInfo startup,out ProcessInformation information);
    [DllImport("kernel32.dll",SetLastError=true)]private static extern uint ResumeThread(IntPtr thread);[DllImport("kernel32.dll",SetLastError=true)]private static extern bool TerminateProcess(IntPtr process,uint code);[DllImport("kernel32.dll",SetLastError=true)]private static extern uint WaitForSingleObject(IntPtr process,uint milliseconds);
    [DllImport("kernel32.dll",SetLastError=true)]private static extern IntPtr CreateJobObject(IntPtr attributes,string name);[DllImport("kernel32.dll",SetLastError=true)]private static extern bool SetInformationJobObject(IntPtr job,int infoClass,ref ExtendedLimitInformation info,uint length);[DllImport("kernel32.dll",SetLastError=true)]private static extern bool AssignProcessToJobObject(IntPtr job,IntPtr process);[DllImport("kernel32.dll",SetLastError=true)]private static extern bool QueryInformationJobObject(IntPtr job,int infoClass,IntPtr info,uint length,IntPtr returnLength);[DllImport("kernel32.dll",SetLastError=true)]private static extern bool TerminateJobObject(IntPtr job,uint code);[DllImport("kernel32.dll",SetLastError=true)]private static extern IntPtr GetStdHandle(int standardHandle);[DllImport("kernel32.dll",SetLastError=true)]private static extern bool CloseHandle(IntPtr handle);
}
'@
}
function Fail-M12([string]$code) { throw "M12-OBSERVABILITY-$code" }
function Assert-M12TrustedTree([string]$path) {
    $full = [IO.Path]::GetFullPath($path); $root = [IO.Path]::GetPathRoot($full); $cursor = $root
    foreach ($part in ($full.Substring($root.Length) -split '[\\/]')) { if ([string]::IsNullOrEmpty($part)) { continue }; $cursor = Join-Path $cursor $part; if (-not (Test-Path -LiteralPath $cursor)) { continue }; $item = Get-Item -LiteralPath $cursor -Force; if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Fail-M12 'PATH' } }
}
function Get-M12Sha256([string]$path) { (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Normalize-M12NativePath([string]$path) { if ($path.StartsWith('\\?\UNC\',[StringComparison]::OrdinalIgnoreCase)) { return '\\' + $path.Substring(8) }; if ($path.StartsWith('\\?\',[StringComparison]::OrdinalIgnoreCase)) { return $path.Substring(4) }; return $path }
function Read-M12LockedBytes([string]$path,[int]$maximum) {
    Assert-M12TrustedTree $path
    $stream = [IO.FileStream]::new($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None)
    try { if ($stream.Length -lt 1 -or $stream.Length -gt $maximum) { Fail-M12 'OUTPUT' }; $bytes=[byte[]]::new([int]$stream.Length);$offset=0;while($offset -lt $bytes.Length){$n=$stream.Read($bytes,$offset,$bytes.Length-$offset);if($n -le 0){Fail-M12 'OUTPUT'};$offset+=$n}; return $bytes } finally { $stream.Dispose() }
}
function Get-M12LockedSnapshot([string]$path,[int]$maximum) { Assert-M12TrustedTree $path;$stream=[IO.FileStream]::new($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None);try{if($stream.Length-lt1-or$stream.Length-gt$maximum){Fail-M12 'OUTPUT'};$identity=if($IsWindows){[M12OutputFile]::Read($stream)}else{[pscustomobject]@{Links=1;FinalPath=[IO.Path]::GetFullPath($path)}};$bytes=[byte[]]::new([int]$stream.Length);$offset=0;while($offset-lt$bytes.Length){$read=$stream.Read($bytes,$offset,$bytes.Length-$offset);if($read-le0){Fail-M12 'OUTPUT'};$offset+=$read};$sha=[Security.Cryptography.SHA256]::Create();try{$hash=[Convert]::ToHexString($sha.ComputeHash($bytes)).ToLowerInvariant()}finally{$sha.Dispose()};return [pscustomobject]@{Bytes=$bytes;Hash=$hash;Identity=$identity}}finally{$stream.Dispose()} }
function Assert-M12SameIdentity([object]$expected,[object]$actual) { if($expected.Links-ne 1-or$actual.Links-ne 1-or($IsWindows-and($expected.Volume-ne$actual.Volume-or$expected.High-ne$actual.High-or$expected.Low-ne$actual.Low))){Fail-M12 'OUTPUT'} }
function Assert-M12JsonNoDuplicateProperties([Text.Json.JsonElement]$element) { if($element.ValueKind -eq [Text.Json.JsonValueKind]::Object){$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($property in $element.EnumerateObject()){if(-not$seen.Add($property.Name)){Fail-M12 'OUTPUT'};Assert-M12JsonNoDuplicateProperties $property.Value}}elseif($element.ValueKind -eq [Text.Json.JsonValueKind]::Array){foreach($item in $element.EnumerateArray()){Assert-M12JsonNoDuplicateProperties $item}} }
function Read-M12ClosedJsonBytes([byte[]]$bytes) {
    if ($bytes.Length -lt 1 -or $bytes.Length -gt $MaximumJsonBytes -or $bytes[-1] -ne 10 -or @($bytes | Where-Object { $_ -eq 13 }).Count -ne 0 -or @($bytes | Where-Object { $_ -eq 10 }).Count -ne 1 -or ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191)) { Fail-M12 'OUTPUT' }
    $doc=$null;try{$json=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);$doc=[Text.Json.JsonDocument]::Parse([string]$json);if($doc.RootElement.ValueKind -ne [Text.Json.JsonValueKind]::Object){Fail-M12 'OUTPUT'};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($property in $doc.RootElement.EnumerateObject()){if(-not$seen.Add($property.Name)){Fail-M12 'OUTPUT'}};Assert-M12JsonNoDuplicateProperties $doc.RootElement;return $json.TrimEnd("`n") | ConvertFrom-Json -DateKind String -ErrorAction Stop}catch{if($_.Exception.Message -like 'M12-OBSERVABILITY-*'){throw};Fail-M12 'OUTPUT'}finally{if($null -ne $doc){$doc.Dispose()}}
}
function Assert-M12JsonTypesBytes([byte[]]$bytes,[hashtable]$types) { $object=Read-M12ClosedJsonBytes $bytes;foreach($name in $types.Keys){if($null -eq $object.PSObject.Properties[$name]){Fail-M12 'OUTPUT'}};return $object }
function Assert-M12ObjectTypes([object]$value,[hashtable]$types) { foreach($name in $types.Keys){$p=$value.PSObject.Properties[$name];if($null -eq $p){Fail-M12 'OUTPUT'};switch($types[$name]){'string'{if($p.Value -isnot[string]){Fail-M12 'OUTPUT'}}'integer'{if($p.Value -isnot[int] -and $p.Value -isnot[long]){Fail-M12 'OUTPUT'}}'boolean'{if($p.Value -isnot[bool]){Fail-M12 'OUTPUT'}}}} }
function Assert-M12ExactJsonShape([byte[]]$bytes,[string[]]$names,[hashtable]$types) { $value=Read-M12ClosedJsonBytes $bytes;if((@($value.PSObject.Properties.Name)-join '|') -cne ($names -join '|')){Fail-M12 'OUTPUT'};foreach($name in $names){$property=$value.PSObject.Properties[$name];if($null -eq $property){Fail-M12 'OUTPUT'};$kind=$types[$name];if($kind -eq 'string' -and $property.Value -isnot [string]){Fail-M12 'OUTPUT'}elseif($kind -eq 'integer' -and $property.Value -isnot [int] -and $property.Value -isnot [long]){Fail-M12 'OUTPUT'}elseif($kind -eq 'object' -and ($property.Value -is [string] -or $null -eq $property.Value -or $property.Value.PSObject.Properties.Count -eq 0)){Fail-M12 'OUTPUT'}};return $value }
function Read-M12LiveJsonBytes([byte[]]$bytes) { if($bytes.Length-lt 2-or$bytes.Length-gt$MaximumJsonBytes-or@($bytes|Where-Object{$_ -eq 13}).Count-ne 0-or($bytes.Length-ge 3-and$bytes[0]-eq239-and$bytes[1]-eq187-and$bytes[2]-eq191)){Fail-M12 'OUTPUT'};$json=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);$doc=$null;try{$doc=[Text.Json.JsonDocument]::Parse([string]$json);if($doc.RootElement.ValueKind-ne[Text.Json.JsonValueKind]::Object){Fail-M12 'OUTPUT'};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($p in $doc.RootElement.EnumerateObject()){if(-not$seen.Add($p.Name)){Fail-M12 'OUTPUT'}};Assert-M12JsonNoDuplicateProperties $doc.RootElement;return $json|ConvertFrom-Json -DateKind String -ErrorAction Stop}catch{if($_.Exception.Message-like'M12-OBSERVABILITY-*'){throw};Fail-M12 'OUTPUT'}finally{if($null-ne$doc){$doc.Dispose()}} }
function Assert-M12ObservabilityFacts([object]$result,[string]$caseId) { $names=if($caseId-ceq'm12-readiness-observability'){@('readiness','otel','postgresMajorVersion','activityCount','attributeCount','bounded')}else{@('telemetry','otel','measurements','attributeCount','sensitiveDataFree')};$types=@{};foreach($name in $names){$types[$name]=if($name-in @('readiness','otel','telemetry','bounded','sensitiveDataFree')){'boolean'}else{'integer'}};if((@($result.facts.PSObject.Properties.Name)-join'|')-cne($names-join'|')){Fail-M12 'TEST'};foreach($name in $names){$p=$result.facts.PSObject.Properties[$name];if($types[$name]-eq'boolean' -and $p.Value -isnot[bool]){Fail-M12 'TEST'};if($types[$name]-eq'integer' -and ($p.Value -isnot[int] -and $p.Value -isnot[long] -or [long]$p.Value -lt 0)){Fail-M12 'TEST'}};if($caseId-ceq'm12-readiness-observability' -and($result.facts.readiness-ne$true-or$result.facts.otel-ne$true-or$result.facts.postgresMajorVersion-ne18-or$result.facts.bounded-ne$true)){Fail-M12 'TEST'};if($caseId-ceq'm12-telemetry-observability' -and($result.facts.telemetry-ne$true-or$result.facts.otel-ne$true-or$result.facts.sensitiveDataFree-ne$true)){Fail-M12 'TEST'};return $result.facts }
function Write-M12AtomicJson([string]$path,[object]$value) { $bytes=[Text.UTF8Encoding]::new($false).GetBytes(($value|ConvertTo-Json -Depth 32 -Compress)+"`n");if($bytes.Length -gt $MaximumJsonBytes -or (Test-Path -LiteralPath $path)){Fail-M12 'OUTPUT'};$stream=[IO.FileStream]::new($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[void](Assert-M12OutputFileIdentity $path (Split-Path $path -Parent))}
function Remove-M12SafeDescendants([string]$path,[string]$root) { $full=[IO.Path]::GetFullPath($path);$rootFull=[IO.Path]::GetFullPath($root);if(-not $full.StartsWith($rootFull+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){Fail-M12 'PROCESS'};$item=Get-Item -LiteralPath $full -Force -ErrorAction Stop;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0){Fail-M12 'PROCESS'};if($item.PSIsContainer){foreach($child in @(Get-ChildItem -LiteralPath $full -Force -ErrorAction Stop)){Remove-M12SafeDescendants $child.FullName $rootFull};Remove-Item -LiteralPath $full -Force -ErrorAction Stop}else{Remove-Item -LiteralPath $full -Force -ErrorAction Stop};if(Test-Path -LiteralPath $full){Fail-M12 'PROCESS'} }
function Remove-M12RawTestDirectory([string]$path) { if(-not(Test-Path -LiteralPath $path)){return};Assert-M12TrustedTree $path;foreach($entry in @(Get-ChildItem -LiteralPath $path -Force)){Remove-M12SafeDescendants $entry.FullName $path};Remove-Item -LiteralPath $path -Force -ErrorAction Stop;if(Test-Path -LiteralPath $path){Fail-M12 'OUTPUT'} }
function Remove-M12RawArtifactsDirectory([string]$path,[string]$parent) { if(-not(Test-Path -LiteralPath $path)){return};$full=[IO.Path]::GetFullPath($path);$base=[IO.Path]::GetFullPath($parent).TrimEnd('\','/');if(-not $full.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)-or[IO.Path]::GetFileName($full)-cne'raw'){Fail-M12 'OUTPUT'};Remove-M12RawTestDirectory $full }
function Assert-M12CleanTree([string]$root) { Invoke-M12GitStatus $root }
function Open-M12ExecutableHandle([string]$path) { if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Fail-M12 'EXECUTABLE'};Assert-M12TrustedTree $path;$stream=[IO.FileStream]::new($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);if($IsWindows){$id=[M12OutputFile]::Read($stream);if($id.Links -ne 1 -or [IO.Path]::GetFullPath((Normalize-M12NativePath $id.FinalPath))-ine[IO.Path]::GetFullPath($path)){$stream.Dispose();Fail-M12 'EXECUTABLE'}};return [pscustomobject]@{Stream=$stream} }
function Assert-M12OutputFileIdentity([string]$path,[string]$directory) { $full=[IO.Path]::GetFullPath($path);$base=[IO.Path]::GetFullPath($directory).TrimEnd('\','/');if(-not $full.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)-or[IO.Path]::GetFileName($full)-notmatch'^[a-z0-9-]+\.(json|trx)$'){Fail-M12 'OUTPUT'};Assert-M12TrustedTree $full;if($IsWindows){$stream=[IO.FileStream]::new($full,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None);try{$id=[M12OutputFile]::Read($stream);if($id.Links -ne 1 -or [IO.Path]::GetFullPath((Normalize-M12NativePath $id.FinalPath))-ine$full){Fail-M12 'OUTPUT'};return $id}finally{$stream.Dispose()}};return [pscustomobject]@{Links=1;FinalPath=$full} }
function Assert-M12ObservedPidsExited([Collections.Generic.HashSet[int]]$processIds) { if(-not$IsWindows){return};foreach($id in $processIds){$remaining=@(Get-CimInstance Win32_Process -Filter "ProcessId=$id" -ErrorAction Stop);if($remaining.Count -ne 0){Fail-M12 'PROCESS'}} }
function Assert-M12PublishedArtifacts([string]$build) { $expected=@("$CaseId-evidence.json","$CaseId-result.json","$CaseId-provenance.json");$entries=@(Get-ChildItem -LiteralPath $build -File);if($entries.Count -ne 3 -or ((@($entries.Name|Sort-Object)-join'|') -cne (@($expected|Sort-Object)-join'|'))){Fail-M12 'OUTPUT'};foreach($entry in $entries){$script:M12OutputHashes[$entry.Name]=Get-M12Sha256 $entry.FullName;$script:M12OutputBytes[$entry.Name]=Read-M12LockedBytes $entry.FullName 32768;[void](Assert-M12OutputFileIdentity $entry.FullName $build)};$detailBytes=$script:M12OutputBytes["$CaseId-evidence.json"];$resultBytes=$script:M12OutputBytes["$CaseId-result.json"];$provBytes=$script:M12OutputBytes["$CaseId-provenance.json"];$detail=Read-M12ClosedJsonBytes $detailBytes;$result=Read-M12ClosedJsonBytes $resultBytes;$prov=Read-M12ClosedJsonBytes $provBytes;if((@($detail.PSObject.Properties.Name)-join'|')-cne'schemaVersion|caseId|producerId|kind|result|environmentId|testName|facts|contractSha256|contractSchemaSha256|testCount'){Fail-M12 'OUTPUT'};if((@($result.PSObject.Properties.Name)-join'|')-cne'caseId|status|executions|skipped|notRun|failed|runId|commitSha|environmentId'){Fail-M12 'OUTPUT'};if((@($prov.PSObject.Properties.Name)-join'|')-cne'artifactId|kind|producerId|artifactSha256|artifactSize|commitSha|runId|environmentId|createdAtUtc'){Fail-M12 'OUTPUT'};Assert-M12ObjectTypes $detail @{schemaVersion='integer';caseId='string';producerId='string';kind='string';result='string';environmentId='string';testName='string';contractSha256='string';contractSchemaSha256='string';testCount='integer'};Assert-M12ObjectTypes $result @{caseId='string';status='string';executions='integer';skipped='integer';notRun='integer';failed='integer';runId='string';commitSha='string';environmentId='string'};Assert-M12ObjectTypes $prov @{artifactId='string';kind='string';producerId='string';artifactSha256='string';artifactSize='integer';commitSha='string';runId='string';environmentId='string';createdAtUtc='string'};if($detail.schemaVersion-ne1-or$detail.caseId-cne$CaseId-or$detail.producerId-cne$ProducerId-or$detail.kind-cne$ArtifactKind-or$detail.result-cne'passed'-or$detail.testCount-ne1-or$detail.contractSha256-cne$ApprovedContractSha256-or$detail.contractSchemaSha256-cne$ApprovedContractSchemaSha256){Fail-M12 'OUTPUT'};if($result.caseId-cne$CaseId-or$result.status-cne'passed'-or$result.executions-ne1-or$result.skipped-ne0-or$result.notRun-ne0-or$result.failed-ne0-or$result.commitSha-cne$commit-or$result.environmentId-cne$environmentId){Fail-M12 'OUTPUT'};$guid=[Guid]::Empty;if(-not[Guid]::TryParse([string]$result.runId,[ref]$guid)-or$guid.ToString('D')-cne$runId){Fail-M12 'OUTPUT'};if($prov.artifactId-cne$CaseId-or$prov.kind-cne$ArtifactKind-or$prov.producerId-cne$ProducerId-or$prov.artifactSha256-cne$script:M12OutputHashes["$CaseId-evidence.json"]-or[long]$prov.artifactSize-ne[long]$detailBytes.Length-or$prov.commitSha-cne$commit-or$prov.runId-cne$runId-or$prov.environmentId-cne$environmentId){Fail-M12 'OUTPUT'};try{$at=[DateTimeOffset]::ParseExact([string]$prov.createdAtUtc,"yyyy-MM-dd'T'HH:mm:ss.fffffff'Z'",[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AssumeUniversal)}catch{Fail-M12 'OUTPUT'};if($at-lt[DateTimeOffset]::UtcNow.AddMinutes(-5)-or$at-gt[DateTimeOffset]::UtcNow.AddMinutes(5)){Fail-M12 'OUTPUT'} }
function Read-M12ObservabilityTrx([string]$path,[string]$expectedTestName) { $bytes=Read-M12LockedBytes $path 16777216;$text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);if($text-match'(?is)<!DOCTYPE'){Fail-M12 'TEST'};$xml=[Xml.XmlDocument]::new();$xml.XmlResolver=$null;$stream=[IO.MemoryStream]::new($bytes);try{$xml.Load($stream)}catch{Fail-M12 'TEST'}finally{$stream.Dispose()};if($null-ne$xml.DocumentType){Fail-M12 'TEST'};$roots=@($xml.SelectNodes('/*'));$results=@($xml.SelectNodes('//*[local-name()="UnitTestResult"]'));$units=@($xml.SelectNodes('//*[local-name()="UnitTest"]'));$summaries=@($xml.SelectNodes('//*[local-name()="ResultSummary"]'));if($roots.Count-ne 1-or$roots[0].LocalName-cne'TestRun'-or$results.Count-ne 1-or$units.Count-ne 1-or$summaries.Count-ne 1){Fail-M12 'TEST'};$result=$results[0];$unit=$units[0];$summary=$summaries[0];if($result.ParentNode.LocalName-cne'Results'-or$unit.ParentNode.LocalName-cne'TestDefinitions'-or$summary.ParentNode.LocalName-cne'TestRun'-or[string]$summary.outcome-cne'Completed'-or[string]$result.testName-cne$expectedTestName-or[string]$unit.name-cne$expectedTestName-or[string]$result.testId-cne[string]$unit.id-or[string]$result.outcome-cne'Passed'){Fail-M12 'TEST'};$counter=@($summary.ChildNodes|Where-Object LocalName -ceq 'Counters');if($counter.Count-ne 1){Fail-M12 'TEST'};$expected=[ordered]@{total=1;executed=1;passed=1;failed=0;error=0;timeout=0;aborted=0;inconclusive=0;passedButRunAborted=0;notRunnable=0;notExecuted=0;disconnected=0;warning=0;completed=0;inProgress=0;pending=0};foreach($name in $expected.Keys){$attribute=$counter[0].Attributes[$name];$number=0;if($null -eq $attribute -or -not[int]::TryParse($attribute.Value,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$number)-or$number-ne$expected[$name]){Fail-M12 'TEST'}};return [pscustomobject]@{TestCount=1;Bytes=$bytes} }
function Read-M12Json([string]$path) {
    $bytes=[IO.File]::ReadAllBytes($path);if($bytes.Length-lt 1-or$bytes.Length-gt$MaximumJsonBytes){Fail-M12 'CONTRACT'};$doc=$null;try{$json=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);$doc=[Text.Json.JsonDocument]::Parse([string]$json);if($doc.RootElement.ValueKind-ne[Text.Json.JsonValueKind]::Object){Fail-M12 'CONTRACT'};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($property in $doc.RootElement.EnumerateObject()){if(-not$seen.Add($property.Name)){Fail-M12 'CONTRACT'}};Assert-M12JsonNoDuplicateProperties $doc.RootElement;return $json|ConvertFrom-Json -DateKind String -ErrorAction Stop}catch{if($_.Exception.Message-like'M12-OBSERVABILITY-*'){throw};Fail-M12 'CONTRACT'}finally{if($null-ne$doc){$doc.Dispose()}}
}
function Assert-M12ClosedSchema([object]$node) { if($null -eq $node){return};if($node.PSObject.Properties.Name -contains 'additionalProperties' -and $node.additionalProperties -ne $false){Fail-M12 'CONTRACT'};foreach($property in $node.PSObject.Properties){if($property.Name -eq 'properties'){foreach($child in $property.Value.PSObject.Properties){Assert-M12ClosedSchema $child.Value}}elseif($property.Name -eq 'items' -and $property.Value -isnot [bool]){Assert-M12ClosedSchema $property.Value}} }
