}
function Assert-M12ObservabilityConnection([string]$connection) {
    if([string]::IsNullOrWhiteSpace($connection)-or$connection.Length-gt 4096){Fail-M12 'INPUT'};$parts=[ordered]@{};foreach($segment in [regex]::Split($connection,';')){$text=$segment.Trim();if($text.Length-eq 0){Fail-M12 'INPUT'};$equals=$text.IndexOf('=');if($equals-lt 1){Fail-M12 'INPUT'};$key=$text.Substring(0,$equals).Trim().ToLowerInvariant();$value=$text.Substring($equals+1).Trim();if($parts.Contains($key)-or$value.Length-eq 0){Fail-M12 'INPUT'};if($value.Contains("'")-or$value.Contains('"')){Fail-M12 'INPUT'};$parts[$key]=$value};$allowed=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);foreach($key in @('host','database','ssl mode','port')){[void]$allowed.Add($key)};foreach($key in $parts.Keys){if(-not$allowed.Contains($key)){Fail-M12 'INPUT'}};if(-not$parts.Contains('host')-or-not$parts.Contains('database')-or-not$parts.Contains('ssl mode')-or$parts['ssl mode']-cne'VerifyFull'){Fail-M12 'INPUT'};$hostName=[string]$parts['host'];if($hostName.Contains(',')-or$hostName-match'(?i)(localhost|loopback|desktop|workstation)'){Fail-M12 'INPUT'};$hostToken=$hostName;if($hostToken.StartsWith('[')-and$hostToken.EndsWith(']')){$hostToken=$hostToken.Substring(1,$hostToken.Length-2)}elseif($hostToken.Contains('[')-or$hostToken.Contains(']')){Fail-M12 'INPUT'};if($hostToken.Length-eq 0){Fail-M12 'INPUT'};$isNumericAlias=$hostToken-match'^(?i:0x[0-9a-f]+|[0-9]+(?:\.[0-9]+){0,3})$';$isNumericTrailingDot=$hostToken-match'^(?i:0x[0-9a-f]+|[0-9]+(?:\.[0-9]+){0,3})\.$';$isCanonicalIpv4=$hostToken-match'^(?:0|[1-9][0-9]{0,2})(?:\.(?:0|[1-9][0-9]{0,2})){3}$';if($isNumericTrailingDot-or($isNumericAlias-and-not$isCanonicalIpv4)){Fail-M12 'INPUT'};$address=[Net.IPAddress]::None;$isIp=[Net.IPAddress]::TryParse($hostToken,[ref]$address);if($isIp){$normalizedAddress=$address;if($address.IsIPv4MappedToIPv6){$normalizedAddress=$address.MapToIPv4()};$isAny=$normalizedAddress.Equals([Net.IPAddress]::Any)-or$normalizedAddress.Equals([Net.IPAddress]::IPv6Any);$isIpv4LinkLocal=$normalizedAddress.AddressFamily-eq[Net.Sockets.AddressFamily]::InterNetwork-and(([byte[]]$normalizedAddress.GetAddressBytes())[0]-eq169)-and(([byte[]]$normalizedAddress.GetAddressBytes())[1]-eq254);if([Net.IPAddress]::IsLoopback($normalizedAddress)-or$isAny-or$normalizedAddress.IsIPv6LinkLocal-or$isIpv4LinkLocal){Fail-M12 'INPUT'}}elseif($isNumericAlias){Fail-M12 'INPUT'};if($parts.Contains('port')){$port=0;if(-not[int]::TryParse($parts['port'],[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$port)-or$port-lt1-or$port-gt65535){Fail-M12 'INPUT'}}
}
function Assert-M12NoExternalOtlp { foreach($name in $M12ForbiddenOtlpEnvironmentNames){if(-not [string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name))){Fail-M12 'INPUT'}};foreach($entry in [Environment]::GetEnvironmentVariables().GetEnumerator()){if(([string]$entry.Key).StartsWith('OTEL_',[StringComparison]::Ordinal)-and-not [string]::IsNullOrWhiteSpace([string]$entry.Value)){Fail-M12 'INPUT'};if(([string]$entry.Key).StartsWith('SqlObserver__Observability__',[StringComparison]::OrdinalIgnoreCase)-and-not [string]::IsNullOrWhiteSpace([string]$entry.Value)){Fail-M12 'INPUT'}} }
function Invoke-M12GitStatus([string]$root) {
    $run=Invoke-M12GitCommand $root @('status','--porcelain=v1','--untracked-files=all','--no-renames');if($run.ExitCode-ne 0-or$run.TooLarge-or$run.TimedOut-or-not[string]::IsNullOrEmpty($run.Error.Trim())-or-not[string]::IsNullOrEmpty($run.Output.Trim())){Fail-M12 'COMMIT'}
