function Invoke-M12GitCommand([string]$root,[string[]]$arguments) { $git=Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFiles)) 'Git/cmd/git.exe';$handle=Open-M12ExecutableHandle $git;$envNames=@('GIT_DIR','GIT_WORK_TREE','GIT_INDEX_FILE','GIT_OBJECT_DIRECTORY','GIT_ALTERNATE_OBJECT_DIRECTORIES','GIT_CEILING_DIRECTORIES','GIT_COMMON_DIR','GIT_NAMESPACE','GIT_PREFIX','GIT_EXEC_PATH','GIT_SSH','GIT_SSH_COMMAND','GIT_ASKPASS','SSH_ASKPASS','GIT_GUI','GIT_CONFIG','GIT_CONFIG_GLOBAL','GIT_CONFIG_SYSTEM','GIT_CONFIG_NOSYSTEM','GIT_CONFIG_COUNT','GIT_TERMINAL_PROMPT','GIT_PAGER','GIT_EDITOR','GCM_INTERACTIVE');$saved=@{};try{foreach($name in $envNames){$saved[$name]=[Environment]::GetEnvironmentVariable($name);[Environment]::SetEnvironmentVariable($name,$null)};[Environment]::SetEnvironmentVariable('GIT_CONFIG_NOSYSTEM','1');[Environment]::SetEnvironmentVariable('GIT_CONFIG_GLOBAL','NUL');[Environment]::SetEnvironmentVariable('GIT_CONFIG_SYSTEM','NUL');[Environment]::SetEnvironmentVariable('GIT_CONFIG_COUNT','0');[Environment]::SetEnvironmentVariable('GIT_TERMINAL_PROMPT','0');[Environment]::SetEnvironmentVariable('GIT_PAGER','cat');$fullArgs=@('-c','core.fsmonitor=false','-c','core.pager=cat','-c','core.askPass=','-c','credential.helper=','-c','include.path=','-c','core.hooksPath=NUL','--no-optional-locks','-C',$root)+$arguments;return Invoke-M12BoundedProcess $git $fullArgs $root}finally{$handle.Stream.Dispose();foreach($name in $saved.Keys){[Environment]::SetEnvironmentVariable($name,$saved[$name])}} }
function Get-M12CurrentCommit([string]$root) { $run=Invoke-M12GitCommand $root @('rev-parse','--verify','HEAD');if($run.ExitCode-ne 0-or$run.TooLarge-or$run.TimedOut-or-not[string]::IsNullOrEmpty($run.Error.Trim())){Fail-M12 'COMMIT'};$commit=$run.Output.Trim();if($commit-notmatch'^[0-9a-f]{40}$'){Fail-M12 'COMMIT'};return $commit }
function Read-M12BoundedStream([IO.Stream]$stream,[int]$maximum) {
